import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { DEFAULT_STATE } from '../../js/state/schema.js';
import { CONTROL_SPECS, getModuleControlSpecs } from '../../js/ui/control-spec.js';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const html = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');

// Controls whose markup is generated by module-controls.js rather than index.html.
const RENDERED_BY_JS = new Set(['mtgMethanolSplit', 'exploratoryOmPercent']);

function findTag(id) {
  return html.match(new RegExp(`<(input|select)\\b[^>]*\\bid="${id}"[^>]*>`))?.[0] || null;
}

function attr(tag, name) {
  return tag.match(new RegExp(`\\b${name}="([^"]*)"`))?.[1] ?? null;
}

function readoutText(id) {
  const match = html.match(new RegExp(`id="${id}Value">([^<]*)<`));
  return match ? match[1] : null;
}

const fakeApp = { state: DEFAULT_STATE };
const allSpecs = [...CONTROL_SPECS, ...getModuleControlSpecs(DEFAULT_STATE)];

test('control spec ids are unique and every state key has a default', () => {
  const ids = allSpecs.map(spec => spec.id);
  assert.deepEqual(ids.filter((id, index) => ids.indexOf(id) !== index), []);

  allSpecs.forEach(spec => {
    const stateKey = spec.stateKey || spec.id;
    assert.ok(stateKey in DEFAULT_STATE, `Expected DEFAULT_STATE.${stateKey} for control #${spec.id}`);
    assert.ok(['range', 'checkbox', 'select', 'number'].includes(spec.type), `Unknown type on #${spec.id}`);
    if (spec.type === 'range') assert.equal(typeof spec.format, 'function', `Expected a formatter on #${spec.id}`);
  });
});

test('static controls exist in index.html', () => {
  CONTROL_SPECS
    .filter(spec => !RENDERED_BY_JS.has(spec.id))
    .forEach(spec => assert.ok(findTag(spec.id), `Expected #${spec.id} in index.html`));
});

test('index.html pre-JS values and read-outs match DEFAULT_STATE', () => {
  CONTROL_SPECS.forEach(spec => {
    const tag = findTag(spec.id);
    if (!tag) return;
    const stateValue = DEFAULT_STATE[spec.stateKey || spec.id];

    if (spec.type === 'range' || spec.type === 'number') {
      assert.equal(Number(attr(tag, 'value')), stateValue, `#${spec.id} value attribute should match DEFAULT_STATE`);
    }
    if (spec.type === 'range') {
      assert.equal(readoutText(spec.id), spec.format(stateValue, fakeApp), `#${spec.id}Value text should match its formatter`);
    }
    if (spec.type === 'checkbox') {
      assert.equal(/\schecked\b/.test(tag), Boolean(stateValue), `#${spec.id} checked attribute should match DEFAULT_STATE`);
    }
  });
});

test('reference-data driven selects carry no hard-coded options', () => {
  ['mountingType', 'methaneMarketPreset', 'policyMode', 'aiReliabilityTarget', 'locationPreset'].forEach(id => {
    assert.match(html, new RegExp(`<select id="${id}"></select>`), `Expected #${id} options to be generated from data`);
  });
});
